import * as THREE from 'three';
import {TWIN_TONE} from './twin-tone.js';
import {TWIN_FEATURES} from './twin-features.js';

const vintage='https://retrofret.com/products/fender-twin-reverb-ac-568-wfactory-jbls-large-combo-tube-amplifier-1968-13479';
const partReferences=[
 {id:'speakers',label:'Speakers',title:'Where electricity becomes sound.',body:'The signal moves a coil inside a magnet. The attached paper cone pushes air, turning that movement into the sound you hear.',detail:'This study: two 12-inch Oxford-family speakers, each 8 Ω, connected in parallel for a 4 Ω load. Speaker suppliers and factory options varied; JBL D120Fs were an extra-cost option.',image:'./assets/explore/speaker-nubert.jpg',alt:'Rear of a representative loudspeaker showing its basket and magnet.',caption:'Representative loudspeaker construction. This is a Nubert driver, not a Fender, Oxford or JBL part.',credit:'Günther Nubert / Wikimedia Commons · public domain',photoSource:'https://commons.wikimedia.org/wiki/File:12zollhinten.jpg',source:'https://www.vintageguitarandbass.com/fender/catalogues/1968_32.php',sourceLabel:'1968 Fender catalog'},
 {id:'power-tubes',label:'Power tubes',title:'The muscle behind the music.',body:'Four 6L6GC power tubes work together to supply the changing electrical power that ultimately drives the speakers. The smaller tubes nearby handle earlier stages and effects.',detail:'Four large output tubes and six smaller tubes are shown. Their envelopes and positions are a teaching approximation, not a socket-by-socket service diagram.',image:'./assets/explore/6l6gc-joe-haupt.jpg',alt:'Vintage RCA 6L6GC glass power tubes photographed on a light background.',caption:'Representative vintage RCA 6L6GC tubes made for McIntosh. Not the tubes from this Fender specimen.',credit:'Joe Haupt · CC BY-SA 2.0 · unmodified photograph',photoSource:'https://commons.wikimedia.org/wiki/File:Vintage_RCA_Blackplate_6L6GC_Vacuum_Tubes_Made_For_McIntosh,_Made_In_USA_(15643635699).jpg',license:'https://creativecommons.org/licenses/by-sa/2.0/',source:'https://support.fender.com/hc/en-us/articles/42507659450779-What-tubes-are-in-my-amp',sourceLabel:'Fender tube reference'},
 {id:'output-transformer',label:'Output transformer',title:'Connecting tubes to speakers.',body:'The output transformer couples the power tubes to the speakers, matching their very different electrical needs. Its coils and iron core transfer the changing audio signal.',detail:'The dark laminated block is an approximate construction marker. Exact 1968 mounting position, dimensions and winding details still need to be established. It is distinct from the mains power transformer.',source:vintage,sourceLabel:'See the vintage Twin photo gallery',empty:'Vintage chassis photographs are available in the linked gallery. An approved close-up is not yet embedded.'}
];
export const twinParts=[...TWIN_FEATURES,...partReferences.map(part=>({...part,...TWIN_TONE[part.id],side:'rear'}))];

// Anchors stay with the shared model. Ray tests suppress markers behind surfaces.
export function createExploration({host,stage,camera,stopMotion,focusPart}){
 const layer=document.createElement('div');layer.className='part-hotspots';layer.hidden=true;host.append(layer);
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('hotspot-leaders');layer.append(svg);
 const panel=document.createElement('section');panel.className='part-card';panel.hidden=true;panel.setAttribute('aria-label','Selected amplifier feature');panel.id='part-info';stage.append(panel);
 const hint=document.createElement('p');hint.className='explore-hint';hint.textContent='Explore the Twin · select a marker or rotate for more';hint.hidden=true;stage.append(hint);
 const nav=document.createElement('label');nav.className='feature-menu';nav.hidden=true;nav.innerHTML='<span>Explore a part</span><select aria-label="Explore an amplifier part"><option value="">Choose a feature…</option></select>';stage.append(nav);const menu=nav.querySelector('select');
 for(const side of ['front','rear']){const group=document.createElement('optgroup');group.label=side==='front'?'Controls & cosmetics':'Rear components';for(const p of twinParts.filter(p=>p.side===side)){const option=document.createElement('option');option.value=p.id;option.textContent=p.label;group.append(option)}menu.append(group)}
 let model=null,enabled=false,selected=null,anchors=[],meshes=[],lastButton=null,lastRay=0;const world=new THREE.Vector3(),projected=new THREE.Vector3(),bounds=new THREE.Box3(),ray=new THREE.Raycaster(),direction=new THREE.Vector3(),localCamera=new THREE.Vector3();
 const buttons=twinParts.map(part=>{const b=document.createElement('button');b.className='part-hotspot';b.innerHTML=`<span class="hotspot-symbol" aria-hidden="true">+</span><span class="hotspot-label">${part.label}</span>`;b.setAttribute('aria-label',`Learn about ${part.label.toLowerCase()}`);b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls','part-info');b.onclick=()=>select(part.id,b);layer.append(b);const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('stroke','#d7b47d');line.setAttribute('stroke-width','1');svg.append(line);return {part,b,line,occluded:false};});
 function clear(focus=false){panel.hidden=true;selected=null;menu.value='';stage.classList.remove('part-selected');buttons.forEach(({b})=>b.setAttribute('aria-expanded','false'));if(focus)lastButton?.focus({preventScroll:true});}
 function select(id,button){stopMotion();lastButton=button;selected=id;menu.value=id;const p=twinParts.find(p=>p.id===id);focusPart(p.side);stage.classList.add('part-selected');panel.hidden=false;panel.scrollTop=0;panel.innerHTML=`<button class="part-close" aria-label="Close part information">×</button><span class="eyebrow">EXPLORE THE TWIN / ${p.label.toUpperCase()}</span><h2>${p.title}</h2><p>${p.body}</p><dl class="tone-attributes">${p.attributes.map(([key,value])=>`<div><dt>${key}</dt><dd>${value}</dd></div>`).join('')}</dl><section class="tone-listen"><h3>${p.cosmetic?'The collector angle':'Why it matters'}</h3><p>${p.listen}</p></section><details class="tone-notes"><summary>${p.cosmetic?'Evidence & context':'Follow the circuit'}</summary><p>${p.together}</p>${p.choice?`<h3>Design rationale</h3><span class="interpretation">INTERPRETATION</span><p>${p.choice}</p>`:''}<h3>${p.extraTitle}</h3><p>${p.extra}</p></details><details class="tone-photo"><summary>${p.image?'Photograph & sources':'Sources & reference notes'}</summary>${p.image?`<figure><img src="${p.image}" alt="${p.alt}"><figcaption>${p.caption}</figcaption></figure><p class="photo-credit"><a href="${p.photoSource}" target="_blank" rel="noopener noreferrer">${p.credit}</a>${p.license?` · <a href="${p.license}" target="_blank" rel="noopener noreferrer">License</a>`:''}</p>`:p.empty?`<p class="photo-pending">${p.empty}</p><a class="part-source" href="${p.source}" target="_blank" rel="noopener noreferrer">${p.sourceLabel}</a>`:''}<p class="part-detail">${p.detail}</p><ul class="tone-sources">${p.sources.map(([url,label])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a></li>`).join('')}</ul></details>`;panel.querySelector('button').onclick=()=>clear(true);buttons.forEach(({part,b})=>b.setAttribute('aria-expanded',String(part.id===id)));panel.querySelector('button').focus({preventScroll:true});}
 menu.onchange=()=>{if(menu.value)select(menu.value,menu);else clear()};
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();clear(true)}});
 function visibleHierarchy(o){for(let n=o;n;n=n.parent)if(!n.visible)return false;return true;}
 return {
  attach(next){clear();model=next;enabled=!!model?.userData.exploration;anchors=[];meshes=[];model?.traverse(o=>{if(o.userData.explorePart)anchors.push(o);if(o.isMesh)meshes.push(o)});stage.classList.toggle('construction-demo',enabled);layer.hidden=nav.hidden=hint.hidden=!enabled;lastRay=0;},
  clear,
  update(){if(!enabled)return;model.updateWorldMatrix(true,true);localCamera.copy(camera.position);model.worldToLocal(localCamera);const now=performance.now(),testRays=now-lastRay>100;const placed=[];
   buttons.forEach(item=>{const {part,b,line}=item;const o=anchors.find(o=>o.userData.explorePart===part.id);if(!o){b.hidden=true;line.style.display='none';return;}if(o.userData.explorePoint)o.getWorldPosition(world);else {bounds.setFromObject(o).getCenter(world);if(o.userData.exploreOffset){o.worldToLocal(world);world.add(new THREE.Vector3(...o.userData.exploreOffset));o.localToWorld(world);}}
    projected.copy(world).project(camera);const x=(projected.x*.5+.5)*host.clientWidth,y=(-projected.y*.5+.5)*host.clientHeight;let hidden=projected.z< -1||projected.z>1||x<12||x>host.clientWidth-12||y<12||y>host.clientHeight-12||(part.side==='front'?localCamera.z<.1:localCamera.z>-.1);
    if(!hidden&&testRays){direction.subVectors(world,camera.position);const distance=direction.length();ray.set(camera.position,direction.normalize());ray.far=distance+.02;const hit=ray.intersectObjects(meshes,false).find(h=>visibleHierarchy(h.object));let own=false;for(let n=hit?.object;n;n=n.parent)if(n===o)own=true;item.occluded=!!hit&&!own&&hit.distance<distance-.035;}
    hidden=hidden||item.occluded;b.hidden=hidden;line.style.display=hidden?'none':'';if(hidden)return;
    let bx=x+(part.offset?.[0]||0),by=y+(part.offset?.[1]||0);for(let i=0;i<10&&placed.some(p=>Math.hypot(p.x-bx,p.y-by)<36);i++)by-=36;bx=Math.max(18,Math.min(host.clientWidth-18,bx));by=Math.max(18,Math.min(host.clientHeight-18,by));placed.push({x:bx,y:by});b.style.left=`${bx}px`;b.style.top=`${by}px`;b.classList.toggle('selected',selected===part.id);line.setAttribute('x1',x);line.setAttribute('y1',y);line.setAttribute('x2',bx);line.setAttribute('y2',by);
   });if(testRays)lastRay=now;
  }
 };
}
